import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { ToastContainer } from 'react-toastify';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'react-toastify/dist/ReactToastify.css';
import './styles/custom.css';

// Auth Components
import Login from './components/auth/Login';
import ProtectedRoute from './components/common/ProtectedRoute';
import Layout from './components/common/Layout';
import { AuthProvider } from './contexts/AuthContext';

// User Components
import UserDashboard from './components/user/UserDashboard';
import BookingForm from './components/user/BookingForm';
import MyBookings from './components/user/MyBookings';

// Admin Components
import AdminDashboard from './components/admin/AdminDashboard';
import AllBookings from './components/admin/AllBookings';
import ManageZoom from './components/admin/ManageZoom';

// Logistik Components
import LogistikDashboard from './components/logistik/LogistikDashboard';
import ManageRooms from './components/logistik/ManageRooms';
import RoomBookings from './components/logistik/RoomBookings';

import { USER_ROLES } from './utils/constants';
import { isAuthenticated, getDashboardRoute, getUser } from './utils/auth';

// Root redirect component
const RootRedirect = () => {
  if (!isAuthenticated()) {
    return <Navigate to="/login" replace />;
  }
  
  const user = getUser();
  const dashboardRoute = getDashboardRoute(user?.role);
  return <Navigate to={dashboardRoute} replace />;
};

function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="App">
          <Routes>
            {/* Public Routes */}
            <Route path="/login" element={<Login />} />
            
            {/* Root redirect */}
            <Route path="/" element={<RootRedirect />} />
            
            {/* Protected Routes with Layout */}
            <Route path="/user/*" element={
              <ProtectedRoute requiredRole={USER_ROLES.USER}>
                <Layout>
                  <Routes>
                    <Route path="dashboard" element={<UserDashboard />} />
                    <Route path="booking" element={<BookingForm />} />
                    <Route path="mybookings" element={<MyBookings />} />
                    <Route path="" element={<Navigate to="dashboard" replace />} />
                  </Routes>
                </Layout>
              </ProtectedRoute>
            } />
            
            <Route path="/admin/*" element={
              <ProtectedRoute requiredRole={USER_ROLES.ADMIN}>
                <Layout>
                  <Routes>
                    <Route path="dashboard" element={<AdminDashboard />} />
                    <Route path="bookings" element={<AllBookings />} />
                    <Route path="zoom" element={<ManageZoom />} />
                    <Route path="" element={<Navigate to="dashboard" replace />} />
                  </Routes>
                </Layout>
              </ProtectedRoute>
            } />
            
            <Route path="/logistik/*" element={
              <ProtectedRoute requiredRole={USER_ROLES.LOGISTIK}>
                <Layout>
                  <Routes>
                    <Route path="dashboard" element={<LogistikDashboard />} />
                    <Route path="rooms" element={<ManageRooms />} />
                    <Route path="bookings" element={<RoomBookings />} />
                    <Route path="" element={<Navigate to="dashboard" replace />} />
                  </Routes>
                </Layout>
              </ProtectedRoute>
            } />
            
            {/* Catch all route */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
          
          <ToastContainer
            position="top-right"
            autoClose={3000}
            hideProgressBar={false}
            newestOnTop
            closeOnClick
            rtl={false}
            pauseOnFocusLoss
            draggable
            pauseOnHover
          />
        </div>
      </Router>
    </AuthProvider>
  );
}

export default App;
